import path from "node:path"
const repo = process.env.REPO ?? "/home/user/opencode-v2-plugins/v2-stable/opencode-v2-security"
const { classifyShellCommand } = await import(path.join(repo, "src/security/classifier.ts"))
const wt = process.env.WT ?? "/tmp/opencode"
for (const line of (await Bun.stdin.text()).split("\n")) {
  if (!line.trim()) continue
  const cmd = line.replaceAll("\\n", "\n")
  const d = await classifyShellCommand({ script: cmd, cwd: wt, worktree: wt, shell: "/bin/bash", strictness: (process.env.MODE as any) ?? "LOOSE", permScope: { r: true, w: false, x: true } })
  console.log(`${d.verdict.padEnd(5)} ${d.rules.join(",").padEnd(50)} ${line.slice(0, 110)}`)
}

